package com.nexus.property.auth;
import com.nexus.property.core.*;import jakarta.servlet.http.*;import org.mindrot.jbcrypt.BCrypt;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.security.SecureRandom;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final Db db;private final JwtService jwt;public AuthController(Db db,JwtService jwt){this.db=db;this.jwt=jwt;}
 private Map<String,Object> summary(Map<String,Object>u){var m=new LinkedHashMap<String,Object>();m.put("id",Rows.s(u,"id"));m.put("fullName",Rows.s(u,"full_name"));m.put("email",Rows.s(u,"email"));m.put("phone",Rows.s(u,"phone"));m.put("role",Rows.s(u,"role"));m.put("enabled",Rows.b(u,"enabled"));m.put("emailVerified",Rows.b(u,"email_verified"));m.put("createdAt",Rows.l(u,"created_at"));return m;}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,Object>b){String email=Objects.toString(b.get("email"),"").trim().toLowerCase(),p=Objects.toString(b.get("password"),"");var u=db.one("SELECT * FROM users WHERE email=?",email);if(u==null)throw Api.error(401,"Email or password is incorrect.");long now=System.currentTimeMillis(),locked=Rows.l(u,"locked_until");if(locked>now)throw Api.error(423,"This account is temporarily locked due to consecutive failed login attempts.");if(!Rows.b(u,"enabled"))throw Api.error(403,"This account is currently disabled. Please contact support.");if(!BCrypt.checkpw(p,Rows.s(u,"password_hash"))){long fails=Rows.l(u,"failed_login_attempts")+1, until=fails>=5?now+900000:0;db.exec("UPDATE users SET failed_login_attempts=?, locked_until=?, updated_at=? WHERE id=?",fails,until==0?null:until,now,Rows.s(u,"id"));throw Api.error(fails>=5?423:401,fails>=5?"Too many failed login attempts. Your account has been temporarily locked for 15 minutes for your security.":"Email or password is incorrect.");}db.exec("UPDATE users SET failed_login_attempts=0, locked_until=NULL,last_login_at=?,updated_at=? WHERE id=?",now,now,Rows.s(u,"id"));boolean rem=Boolean.TRUE.equals(b.get("rememberMe"));String token=jwt.create(Rows.s(u,"id"),Rows.s(u,"email"),Rows.s(u,"role"),Rows.s(u,"full_name"),rem);return Api.ok("Signed in successfully.",Map.of("token",token,"user",summary(u)));}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@RequestBody Map<String,Object>b){String name=Objects.toString(b.get("fullName"),"").trim(),email=Objects.toString(b.get("email"),"").trim().toLowerCase(),pass=Objects.toString(b.get("password"),""),role=Objects.toString(b.getOrDefault("role","CUSTOMER"));if(name.length()<2||!email.contains("@")||pass.length()<8)throw Api.error(400,"Please provide a valid full name, email and password of at least 8 characters.");if(!Set.of("CUSTOMER","PROPERTY_OWNER","AGENT").contains(role))role="CUSTOMER";if(db.one("SELECT id FROM users WHERE email=?",email)!=null)throw Api.error(409,"An account with this email already exists.");String id=db.uuid(),vt=UUID.randomUUID().toString();long now=System.currentTimeMillis();db.exec("INSERT INTO users(id,full_name,email,password_hash,phone,role,enabled,email_verified,verification_token,verification_expires_at,failed_login_attempts,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",id,name,email,BCrypt.hashpw(pass,BCrypt.gensalt(10)),b.get("phone"),role,1,0,vt,now+86400000,0,now,now);String token=jwt.create(id,email,role,name,false);var data=new LinkedHashMap<String,Object>();data.put("token",token);data.put("user",summary(db.one("SELECT * FROM users WHERE id=?",id)));data.put("verificationToken",vt);var out=Api.ok("Account registered successfully. Please verify your email to unlock all features.",data);out.put("verificationToken",vt);return out;}
 @PostMapping("/logout") public Map<String,Object> logout(){return Api.message("Signed out successfully.");}
 @GetMapping("/me") public Map<String,Object> me(HttpServletRequest r){var u=AuthFilter.require(r);var row=db.one("SELECT * FROM users WHERE id=?",u.userId());if(row==null)throw Api.error(404,"User not found.");return Api.ok("User profile retrieved.",summary(row));}
 @PutMapping("/profile") public Map<String,Object> profile(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=AuthFilter.require(r);String n=b.containsKey("fullName")?Objects.toString(b.get("fullName"),"").trim():null;Object phone=b.get("phone");if(n!=null&&n.length()<2)throw Api.error(400,"Full name must be between 2 and 100 characters.");if(n!=null)db.exec("UPDATE users SET full_name=?,updated_at=? WHERE id=?",n,System.currentTimeMillis(),u.userId());if(b.containsKey("phone"))db.exec("UPDATE users SET phone=?,updated_at=? WHERE id=?",phone,System.currentTimeMillis(),u.userId());return Api.ok("Profile updated successfully.",summary(db.one("SELECT * FROM users WHERE id=?",u.userId())));}
 @PutMapping("/change-password") public Map<String,Object> change(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=AuthFilter.require(r);String cur=Objects.toString(b.get("currentPassword"),""),np=Objects.toString(b.get("newPassword"),""),cp=Objects.toString(b.get("confirmPassword"),np);if(np.length()<8||!np.equals(cp))throw Api.error(400,"Password does not meet requirements or passwords do not match.");var row=db.one("SELECT password_hash FROM users WHERE id=?",u.userId());if(row==null||!BCrypt.checkpw(cur,Rows.s(row,"password_hash")))throw Api.error(400,"Current password is incorrect.");db.exec("UPDATE users SET password_hash=?,updated_at=? WHERE id=?",BCrypt.hashpw(np,BCrypt.gensalt(10)),System.currentTimeMillis(),u.userId());return Api.message("Password changed successfully.");}
 @PostMapping("/verify-email") public Map<String,Object> verify(@RequestBody Map<String,Object>b){String t=Objects.toString(b.get("token"),"");var u=db.one("SELECT id FROM users WHERE verification_token=? AND verification_expires_at>?",t,System.currentTimeMillis());if(u==null)throw Api.error(400,"Verification token is invalid or expired.");db.exec("UPDATE users SET email_verified=1,verification_token=NULL,verification_expires_at=NULL,updated_at=? WHERE id=?",System.currentTimeMillis(),Rows.s(u,"id"));return Api.ok("Email verified successfully.",Map.of("message","Email verified successfully."));}
 @PostMapping("/resend-verification") public Map<String,Object> resend(@RequestBody Map<String,Object>b){String email=Objects.toString(b.get("email"),"").trim().toLowerCase(),t=UUID.randomUUID().toString();var u=db.one("SELECT id,email_verified FROM users WHERE email=?",email);if(u!=null&&!Rows.b(u,"email_verified"))db.exec("UPDATE users SET verification_token=?,verification_expires_at=? WHERE id=?",t,System.currentTimeMillis()+86400000,Rows.s(u,"id"));return Api.ok("If an unverified account exists, a new verification token has been generated.",u!=null?Map.of("verificationToken",t):Map.of());}
 @PostMapping("/forgot-password") public Map<String,Object> forgot(@RequestBody Map<String,Object>b){String email=Objects.toString(b.get("email"),"").trim().toLowerCase(),t=UUID.randomUUID().toString().replace("-","");var u=db.one("SELECT id FROM users WHERE email=?",email);if(u!=null)db.exec("UPDATE users SET reset_token=?,reset_token_expires=? WHERE id=?",t,System.currentTimeMillis()+3600000,Rows.s(u,"id"));return Api.ok("If an account exists for this email, password reset instructions have been prepared.",u==null?null:Map.of("demoToken",t));}
 @PostMapping("/reset-password") public Map<String,Object> reset(@RequestBody Map<String,Object>b){String t=Objects.toString(b.get("token"),""),np=Objects.toString(b.get("newPassword"),""),cp=Objects.toString(b.get("confirmPassword"),np);if(np.length()<8||!np.equals(cp))throw Api.error(400,"Password does not meet requirements or passwords do not match.");var u=db.one("SELECT id FROM users WHERE reset_token=? AND reset_token_expires>?",t,System.currentTimeMillis());if(u==null)throw Api.error(400,"Reset token is invalid or expired.");db.exec("UPDATE users SET password_hash=?,reset_token=NULL,reset_token_expires=NULL,failed_login_attempts=0,locked_until=NULL,updated_at=? WHERE id=?",BCrypt.hashpw(np,BCrypt.gensalt(10)),System.currentTimeMillis(),Rows.s(u,"id"));return Api.message("Password reset successfully.");}
 @GetMapping("/users") public Map<String,Object> users(HttpServletRequest r,@RequestParam Map<String,String>q){AuthFilter.role(r,"ADMIN");int page=Math.max(1,Integer.parseInt(q.getOrDefault("page","1"))),size=Math.min(100,Integer.parseInt(q.getOrDefault("size","20"))),off=(page-1)*size;StringBuilder w=new StringBuilder(" WHERE 1=1");List<Object>a=new ArrayList<>();if(q.containsKey("search")){w.append(" AND (full_name LIKE ? OR email LIKE ?)");a.add("%"+q.get("search")+"%");a.add("%"+q.get("search")+"%");}if(q.containsKey("role")&&!"ALL".equals(q.get("role"))){w.append(" AND role=?");a.add(q.get("role"));}if(q.containsKey("enabled")){w.append(" AND enabled=?");a.add(Boolean.parseBoolean(q.get("enabled"))?1:0);}long total=db.scalarLong("SELECT COUNT(*) FROM users"+w,a.toArray());var aa=new ArrayList<>(a);aa.add(size);aa.add(off);var list=db.all("SELECT * FROM users"+w+" ORDER BY created_at DESC LIMIT ? OFFSET ?",aa.toArray()).stream().map(this::summary).toList();return Api.ok("Users listed successfully.",Map.of("users",list,"total",total,"page",page,"totalPages",(int)Math.ceil(total/(double)size)));}
 @PutMapping("/users/{id}/role") public Map<String,Object> role(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){var a=AuthFilter.role(r,"ADMIN");String role=Objects.toString(b.get("role"),"");if(!Set.of("CUSTOMER","PROPERTY_OWNER","AGENT","ADMIN").contains(role))throw Api.error(400,"Invalid role specified.");if(a.userId().equals(id)&&!"ADMIN".equals(role))throw Api.error(400,"Administrators cannot demote their own account.");db.exec("UPDATE users SET role=?,updated_at=? WHERE id=?",role,System.currentTimeMillis(),id);audit(a.userId(),"USER_ROLE_CHANGED","USER",id,"Role changed to "+role);return Api.message("User role updated to "+role+".");}
 @PutMapping("/users/{id}/enabled") public Map<String,Object> enabled(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){var a=AuthFilter.role(r,"ADMIN");boolean en=Boolean.TRUE.equals(b.get("enabled"));if(a.userId().equals(id)&&!en)throw Api.error(400,"Administrators cannot disable their own account.");db.exec("UPDATE users SET enabled=?,updated_at=? WHERE id=?",en?1:0,System.currentTimeMillis(),id);audit(a.userId(),en?"USER_ENABLED":"USER_DISABLED","USER",id,"Account status changed");return Api.message("User account "+(en?"enabled":"disabled")+" successfully.");}
 private void audit(String actor,String action,String type,String id,String details){db.exec("INSERT INTO audit_logs(id,actor_id,action,entity_type,entity_id,details,created_at) VALUES(?,?,?,?,?,?,?)",db.uuid(),actor,action,type,id,details,System.currentTimeMillis());}
}
